import { createSlice, createAsyncThunk } from '@reduxjs/toolkit';
import axios from 'axios';

// Async thunk for fetching events
export const fetchEvents = createAsyncThunk('eventOwner/fetchEvents', async () => {
  const token = localStorage.getItem('token');
  const response = await axios.get('http://localhost:5000/api/events', {
    headers: {
      Authorization: `Bearer ${token}`,
    },
  });
  return response.data; // Return the events from the response
});

// Fetch bookings action
export const fetchBookings = createAsyncThunk('eventOwner/fetchBookings', async () => {
  const response = await axios.get('http://localhost:5000/api/bookings');
  return response.data;
});

// Fetch feedbacks action
export const fetchFeedbacks = createAsyncThunk('eventOwner/fetchFeedbacks', async () => {
  const response = await axios.get('http://localhost:5000/api/feedbacks');
  return response.data;
});

// Async thunk for creating a new event
export const createEvent = createAsyncThunk(
  'eventOwner/createEvent',
  async (eventData) => {
    const token = localStorage.getItem('token');
    const response = await axios.post('http://localhost:5000/api/events', eventData, {
      headers: {
        Authorization: `Bearer ${token}`,
      },
    });
    return response.data; // Return the created event
  }
);

// Create the slice
const eventOwnerSlice = createSlice({
  name: 'eventOwner',
  initialState: {
    events: [],
    bookings: [],
    feedbacks: [],
    loading: false,
    error: null,
  },
  reducers: {
    clearEvents: (state) => {
      state.events = [];
    },
  },
  extraReducers: (builder) => {
    builder
      .addCase(fetchEvents.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(fetchEvents.fulfilled, (state, action) => {
        state.loading = false;
        state.events = action.payload; // Set fetched events
      })
      .addCase(fetchEvents.rejected, (state, action) => {
        state.loading = false;
        state.error = action.error.message; // Set error message
      })
      .addCase(createEvent.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(createEvent.fulfilled, (state, action) => {
        state.loading = false;
        state.events.push(action.payload); // Add the newly created event
      })
      .addCase(createEvent.rejected, (state, action) => {
        state.loading = false;
        state.error = action.error.message; // Set error message
      })
      .addCase(fetchBookings.pending, (state) => {
        state.loading = true;
      })
      .addCase(fetchBookings.fulfilled, (state, action) => {
        state.loading = false;
        state.bookings = action.payload;
      })
      .addCase(fetchBookings.rejected, (state, action) => {
        state.loading = false;
        state.error = action.error.message;
      })
      .addCase(fetchFeedbacks.pending, (state) => {
        state.loading = true;
      })
      .addCase(fetchFeedbacks.fulfilled, (state, action) => {
        state.loading = false;
        state.feedbacks = action.payload;
      })
      .addCase(fetchFeedbacks.rejected, (state, action) => {
        state.loading = false;
        state.error = action.error.message;
      });
  },
});

// Export the actions and the reducer
export const { clearEvents } = eventOwnerSlice.actions;
export default eventOwnerSlice.reducer;



